<div class="page-title"><div><em>LENDING OPERATIONS</em><h1>Loan management</h1><p>Review applications and monitor active lending.</p></div><button class="btn" data-modal="loan-modal">+ New loan</button></div><section class="panel"><div class="data-table loan-table"><div class="tr th"><span>Borrower</span><span>Reference</span><span>Principal</span><span>Outstanding</span><span>Rate</span><span>Status</span></div><?php foreach($loans as $l):?><div class="tr"><span class="name"><i><?=initials($l['first_name'].' '.$l['last_name'])?></i><b><?=html_escape($l['first_name'].' '.$l['last_name'])?></b></span><strong><?=$l['reference']?></strong><span><?=money($l['principal'])?></span><strong><?=money($l['outstanding_balance'])?></strong><span><?=$l['interest_rate']?>%</span><span class="<?=status_class($l['status'])?>"><?=ucfirst($l['status'])?></span></div><?php endforeach?></div></section>
<dialog id="loan-modal"><div class="dialog-head"><h2>Issue a new loan</h2><button data-close>×</button></div><?=form_open('admin/loans')?><label>Customer</label><select name="user_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=html_escape($c['first_name'].' '.$c['last_name'])?> (<?=html_escape($c['email'])?>)</option><?php endforeach?></select><div class="form-grid"><div><label>Type</label><select name="type"><option>Personal loan</option><option>Auto loan</option><option>Home improvement</option><option>Education</option></select></div><div><label>Term (months)</label><input name="term_months" type="number" min="6" max="120" value="36" required></div></div><label>Amount</label><input name="amount" type="number" step="0.01" min="1" required><label>Fixed APR (%)</label><input name="interest_rate" type="number" step="0.001" value="6.250"><button class="btn wide">Issue loan</button></form></dialog>
